for (const profile of Object.values(Profiles)) Object.freeze(profile);
export const KIS_MASTER_PROFILES = Object.freeze(Profiles);
export const KisMasterProfileSchema = z.enum(['nas', 'nys', 'ams', 'kospi', 'kosdaq', 'kr_index_derivatives']);
export type KisMasterProfile = z.infer<typeof KisMasterProfileSchema>;
const Timestamp = ExactInstantSchema;
export const KisMasterParseContextSchema = z.object({ profile: KisMasterProfileSchema, origin: z.enum(['actual', 'synthetic']), source_received_at: Timestamp,
  header_mode: z.enum(['none', 'documented_columns']).default('none') }).strict();
const Cell = z.string().max(300).refine(v => !/[\u0000-\u001f\u007f-\u009f\u202a-\u202e\u2066-\u2069\ufffd]/.test(v));
const Code = z.string().min(1).max(16).regex(/^[A-Z0-9][A-Z0-9._-]*$/);
const OptionalDecimal = z.union([z.literal(''), z.string().max(40).regex(/^-?\d+(?:\.\d+)?$/)]);
const OptionalInteger = z.union([z.literal(''), z.string().max(30).regex(/^\d+$/)]);
const SupportedCurrencies = new Set(['USD', 'KRW', 'EUR', 'JPY', 'GBP', 'CNY', 'HKD', 'CAD', 'AUD', 'NZD', 'CHF', 'SGD']);
const OptionalTime = z.union([z.literal(''), z.string().regex(/^(?:[01]\d|2[0-3])[0-5]\d$/)]);
export const KisUsMasterRawSchema = z.object({
  ncod: z.literal('US'), exid: Cell.max(3), excd: z.enum(['NAS', 'NYS', 'AMS']), exnm: Cell.max(16),
  symb: Code, rsym: Code, knam: Cell.max(64), enam: Cell.max(64), stis: z.string().regex(/^\d$/),
  curr: Cell.max(4), zdiv: z.string().regex(/^\d?$/), ztyp: Cell.max(1), base: OptionalDecimal,
  bnit: OptionalInteger, anit: OptionalInteger, mstm: OptionalTime, metm: OptionalTime,
  isdr: z.enum(['Y', 'N', '']), drcd: Cell.max(2), icod: Cell.max(4), sjong: z.enum(['0', '1', '']),
  ttyp: Cell.max(1), etyp: z.union([z.literal(''), z.string().regex(/^\d{3}$/)]), ttyp_sb: Cell.max(3),
}).strict();
export const KisDomesticIndexMasterRawSchema = z.object({
  info_type: z.string().regex(/^[A-Z0-9]$/), shrn_iscd: Code, stnd_iscd: Code,
  kor_name: Cell.min(1).max(100), atm_cls_code: Cell.max(1), acpr: OptionalDecimal,
  mmsc_cls_code: Cell.max(1), unas_shrn_iscd: z.union([Code, z.literal('')]), unas_kor_name: Cell.max(100),
}).strict();
export const KIS_US_MASTER_COLUMNS = Object.freeze([
  'National code', 'Exchange id', 'Exchange code', 'Exchange name', 'Symbol', 'realtime symbol', 'Korea name', 'English name',
  'Security type(1:Index,2:Stock,3:ETP(ETF),4:Warrant)', 'currency', 'float position', 'data type', 'base price', 'Bid order size',
  'Ask order size', 'market start time(HHMM)', 'market end time(HHMM)', 'DR 여부(Y/N)', 'DR 국가코드', '업종분류코드',
  '지수구성종목 존재 여부(0:구성종목없음,1:구성종목있음)', 'Tick size Type',
  '구분코드(001:ETF,002:ETN,003:ETC,004:Others,005:VIX Underlying ETF,006:VIX Underlying ETN)', 'Tick size type 상세',
]);
const US_KEYS = ['ncod', 'exid', 'excd', 'exnm', 'symb', 'rsym', 'knam', 'enam', 'stis', 'curr', 'zdiv', 'ztyp', 'base', 'bnit', 'anit', 'mstm', 'metm', 'isdr', 'drcd', 'icod', 'sjong', 'ttyp', 'etyp', 'ttyp_sb'] as const;
const INDEX_KEYS = ['info_type', 'shrn_iscd', 'stnd_iscd', 'kor_name', 'atm_cls_code', 'acpr', 'mmsc_cls_code', 'unas_shrn_iscd', 'unas_kor_name'] as const;
export type KisMasterErrorCode = 'invalid_input' | 'master_source_not_configured' | 'source_unavailable' | 'source_mismatch' |
  'encoding_invalid' | 'schema_drift' | 'master_too_large' | 'empty_master' | 'duplicate_identity' | 'classification_conflict';
export class KisMasterError extends Error {
  constructor(readonly code: KisMasterErrorCode) { super(code); this.name = 'KisMasterError'; }
}

// Generated from Python 3.12.14's built-in cp949 codec, all 17,048 valid double-byte
// mappings. The 65,536-entry little-endian BMP table is integrity-pinned. Node's
// euc-kr TextDecoder in this runtime does NOT correctly decode UHC 0x8141.
const CP949_TABLE_SHA256 = 'cbb0fe3235481f5a0e98420188f4822908fc8823b8eb0e2ba6bc92acd3a01341';
const CP949_TABLE_DEFLATE_BASE64 = '';
let cp949Table: Buffer | undefined;
function mappingTable(): Buffer {
  if (!cp949Table) {
    const table = inflateSync(Buffer.from(CP949_TABLE_DEFLATE_BASE64, 'base64'), { maxOutputLength: 131072 });
    if (table.length !== 131072 || createHash('sha256').update(table).digest('hex') !== CP949_TABLE_SHA256) throw new KisMasterError('encoding_invalid');
    cp949Table = table;
  }
  return cp949Table;
}
export function decodeKisCp949(bytes: Uint8Array): string {
  if (!(bytes instanceof Uint8Array)) throw new KisMasterError('invalid_input');
  if (bytes.byteLength > KIS_MASTER_MAX_BYTES) throw new KisMasterError('master_too_large');
  const chunks: string[] = [];
  let chunk = '';
  for (let i = 0; i < bytes.length; i++) {
    const first = bytes[i]!;
    if (first < 0x80) chunk += String.fromCharCode(first);
    else {
      const second = bytes[++i];
      if (second === undefined) throw new KisMasterError('encoding_invalid');
      const code = mappingTable().readUInt16LE(((first << 8) | second) * 2);
      if (code === 0) throw new KisMasterError('encoding_invalid');
      chunk += String.fromCharCode(code);
    }
    if (chunk.length >= 4096) { chunks.push(chunk); chunk = ''; }
  }
  chunks.push(chunk);
  return chunks.join('');
}

const ResultMetadata = z.object({
  profile: KisMasterProfileSchema, format_status: z.literal('official_layout_checked_not_live_master_reconciled'),
  source_authenticity: z.literal('unverified_injected_content'), archive_ingestion: z.literal('not_implemented'),
  encoding_status: z.enum(['cp949_bytes_decoded', 'caller_supplied_unicode']), payload_sha256: z.string().regex(/^[a-f0-9]{64}$/),
  rights_status: z.literal('pending'), header_mode: z.enum(['none', 'documented_columns']), row_count: z.number().int().min(1).max(KIS_MASTER_MAX_ROWS),
  warnings: z.array(z.string().max(500)).min(1).max(20),
}).strict();
function checkResult(value: { metadata: z.infer<typeof ResultMetadata>; directory: z.infer<typeof InstrumentDirectorySchema>; records: { source_line: number }[] }, ctx: z.RefinementCtx) {
  if (value.metadata.row_count !== value.records.length || value.records.length !== value.directory.entries.length || value.directory.source_as_of !== null || value.directory.source_url !== Profiles[value.metadata.profile].source_url) ctx.addIssue({ code: 'custom', message: 'master_provenance_conflict' });
  const start = value.metadata.header_mode === 'none' ? 1 : 2;
  if (value.records.some((record, index) => record.source_line !== start + index)) ctx.addIssue({ code: 'custom', message: 'record_line_conflict' });
}
export const KisUsMasterParseResultSchema = z.object({ metadata: ResultMetadata, directory: InstrumentDirectorySchema,
  records: z.array(z.object({ source_line: z.number().int().positive(), raw: KisUsMasterRawSchema }).strict()).min(1).max(KIS_MASTER_MAX_ROWS) }).strict().superRefine((value, ctx) => {
    checkResult(value, ctx);
    if (!['nas', 'nys', 'ams'].includes(value.metadata.profile)) { ctx.addIssue({ code: 'custom', message: 'profile_conflict' }); return; }
    if (new Set(value.records.map(record => record.raw.rsym)).size !== value.records.length) ctx.addIssue({ code: 'custom', message: 'duplicate_realtime_identity' });
    for (const [index, record] of value.records.entries()) {
      const raw = record.raw;
      if (raw.excd !== Profiles[value.metadata.profile].exchange || (raw.stis !== '3' && ['001', '002', '003', '004', '005', '006'].includes(raw.etyp)) || JSON.stringify(value.directory.entries[index]) !== JSON.stringify(usEntry(record, Profiles[value.metadata.profile].filename))) ctx.addIssue({ code: 'custom', message: 'master_identity_conflict' });
    }
  });
export const KisDomesticIndexMasterParseResultSchema = z.object({ metadata: ResultMetadata, directory: InstrumentDirectorySchema,
  records: z.array(z.object({ source_line: z.number().int().positive(), raw: KisDomesticIndexMasterRawSchema }).strict()).min(1).max(KIS_MASTER_MAX_ROWS) }).strict().superRefine((value, ctx) => {
    checkResult(value, ctx);
    if (value.metadata.profile !== 'kr_index_derivatives' || value.metadata.header_mode !== 'none') ctx.addIssue({ code: 'custom', message: 'profile_conflict' });
    if (new Set(value.records.map(record => record.raw.stnd_iscd)).size !== value.records.length) ctx.addIssue({ code: 'custom', message: 'duplicate_standard_identity' });
    if (value.records.some((record, index) => JSON.stringify(value.directory.entries[index]) !== JSON.stringify(indexEntry(record)))) ctx.addIssue({ code: 'custom', message: 'master_identity_conflict' });
  });

function assertPlainRecord(value: unknown, allowed: readonly string[], error: KisMasterErrorCode): void {
  try {
    if (value === null || typeof value !== 'object' || ![Object.prototype, null].includes(Object.getPrototypeOf(value))) throw new KisMasterError(error);
    const keys = Reflect.ownKeys(value);
    if (keys.length > allowed.length) throw new KisMasterError(error);
    for (const key of keys) {
      const descriptor = Object.getOwnPropertyDescriptor(value, key);
      if (typeof key !== 'string' || !allowed.includes(key) || !descriptor?.enumerable || !('value' in descriptor)) throw new KisMasterError(error);
    }
  } catch { throw new KisMasterError(error); }
}

function prepare(contents: string | Uint8Array, context: unknown) {
  assertPlainRecord(context, ['profile', 'origin', 'source_received_at', 'header_mode'], 'invalid_input');
  const parsed = KisMasterParseContextSchema.safeParse(context);
  if (!parsed.success) throw new KisMasterError('invalid_input');
  if (typeof contents !== 'string' && !(contents instanceof Uint8Array)) throw new KisMasterError('invalid_input');
  if ((typeof contents === 'string' ? Buffer.byteLength(contents, 'utf8') : contents.byteLength) > KIS_MASTER_MAX_BYTES) throw new KisMasterError('master_too_large');
  const text = typeof contents === 'string' ? contents : decodeKisCp949(contents);
  if (/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/.test(text) || /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f\ufffd]/.test(text)) throw new KisMasterError('encoding_invalid');
  if (/\r(?!\n)/.test(text)) throw new KisMasterError('schema_drift');
  const lines = text.split(/\r?\n/);
  if (lines.at(-1) === '') lines.pop();
  if (lines.length === 0 || (lines.length === 1 && lines[0] === '')) throw new KisMasterError('empty_master');
  if (lines.length > KIS_MASTER_MAX_ROWS + (parsed.data.header_mode === 'documented_columns' ? 1 : 0)) throw new KisMasterError('master_too_large');
  if (lines.some(line => Buffer.byteLength(line, 'utf8') > 4096)) throw new KisMasterError('master_too_large');
  if (lines.some(line => line === '')) throw new KisMasterError('schema_drift');
  return { context: parsed.data, lines, encoding_status: typeof contents === 'string' ? 'caller_supplied_unicode' as const : 'cp949_bytes_decoded' as const,
    payload_sha256: createHash('sha256').update(contents).digest('hex') };
}

// Python read_table uses CSV-style quoting. Multiline fields are deliberately
// unsupported here, so malformed or open quotes fail instead of dropping records.
function splitRecord(line: string, delimiter: '\t' | '|'): string[] {
  const cells: string[] = []; let field = ''; let quoted = false; let closed = false;
  for (let i = 0; i < line.length; i++) {
    const char = line[i]!;
    if (quoted) {
      if (char === '"') {
        if (line[i + 1] === '"') { field += '"'; i++; } else { quoted = false; closed = true; }
      } else field += char;
    } else if (char === delimiter) { cells.push(field); field = ''; closed = false; }
    else if (char === '"' && field === '' && !closed) quoted = true;
    else { if (closed || char === '"') throw new KisMasterError('schema_drift'); field += char; }
  }
  if (quoted) throw new KisMasterError('schema_drift');
  cells.push(field); return cells;
}
function fields(keys: readonly string[], cells: string[]): Record<string, string> {
  if (keys.length !== cells.length) throw new KisMasterError('schema_drift');
  return Object.fromEntries(keys.map((key, index) => [key, cells[index]!]));
}
function distinct(value: string, seen: Set<string>): void {
  if (seen.has(value)) throw new KisMasterError('duplicate_identity');
  seen.add(value);
}
function metadata(prepared: ReturnType<typeof prepare>, count: number) {
  return { profile: prepared.context.profile, format_status: 'official_layout_checked_not_live_master_reconciled',
    source_authenticity: 'unverified_injected_content', archive_ingestion: 'not_implemented', encoding_status: prepared.encoding_status,
    payload_sha256: prepared.payload_sha256, rights_status: 'pending', header_mode: prepared.context.header_mode, row_count: count,
    warnings: ['Only the supplied extracted file is covered; no actual master was downloaded and authenticity/current listing status is unverified.',
      'Directory entries are candidates, not quote identity confirmation or authorization to use market data.',
      'No archive extraction, automatic refresh, source publication timestamp, CIK or OpenDART corporate-code mapping is supplied.',
      'Unrecognized classification/currency values are not inferred from a market or product name.'] } as const;
}
function directory(prepared: ReturnType<typeof prepare>, entries: z.infer<typeof InstrumentDirectorySchema>['entries'], coverage: string) {
  const result = { origin: prepared.context.origin, source_received_at: prepared.context.source_received_at, source_as_of: null,
    source_url: Profiles[prepared.context.profile].source_url, entries, coverage };
  if (Buffer.byteLength(JSON.stringify(result), 'utf8') > KIS_MASTER_MAX_BYTES) throw new KisMasterError('master_too_large');
  const parsed = InstrumentDirectorySchema.safeParse(result);
  if (!parsed.success) throw new KisMasterError('schema_drift');
  return parsed.data;
}

function usEntry({ source_line, raw }: { source_line: number; raw: z.infer<typeof KisUsMasterRawSchema> }, filename: string) {
  const name = raw.enam.trim() || raw.knam.trim();
  const asset_class = raw.stis === '2' ? 'equity' as const : raw.stis === '3' && ['001', '005'].includes(raw.etyp) ? 'etf' as const : 'unknown' as const;
  return { instrument_ref: `kis:US:${raw.excd}:${raw.symb}`, symbol: raw.symb, name, market: 'US' as const, asset_class,
    exchange: raw.excd, currency: SupportedCurrencies.has(raw.curr) ? raw.curr : null, cik: null, corp_code: null,
    aliases: [...new Set([raw.knam.trim(), raw.enam.trim(), raw.rsym].filter(value => value !== '' && value !== name))],
    source_ref: `kis:${filename}:line:${source_line}` };
}
function indexEntry({ source_line, raw }: { source_line: number; raw: z.infer<typeof KisDomesticIndexMasterRawSchema> }) {
  return { instrument_ref: `kis:KR:idx:${raw.shrn_iscd}`, symbol: raw.shrn_iscd, name: raw.kor_name.trim(), market: 'KR' as const,
    asset_class: ['1', '3', '7', '9', 'B'].includes(raw.info_type) ? 'future' as const : 'unknown' as const,
    exchange: null, currency: null, cik: null, corp_code: null, aliases: [raw.stnd_iscd], source_ref: `kis:fo_idx_code_mts.mst:line:${source_line}` };
}

export function parseKisUsStockMaster(contents: string | Uint8Array, context: unknown) {
  const p = prepare(contents, context);
  if (!['nas', 'nys', 'ams'].includes(p.context.profile)) throw new KisMasterError('invalid_input');
  const profile = Profiles[p.context.profile];
  let start = 0;
  if (p.context.header_mode === 'documented_columns') {
    const header = splitRecord(p.lines[0]!, '\t');
    if (header.length !== KIS_US_MASTER_COLUMNS.length || header.some((value, index) => value !== KIS_US_MASTER_COLUMNS[index])) throw new KisMasterError('schema_drift');
    start = 1;
  }
  if (p.lines.length === start) throw new KisMasterError('empty_master');
  const symbols = new Set<string>(); const realtime = new Set<string>();
  const records = p.lines.slice(start).map((line, index) => {
    const row = KisUsMasterRawSchema.safeParse(fields(US_KEYS, splitRecord(line, '\t')));
    if (!row.success) throw new KisMasterError('schema_drift');
    const raw = row.data;
    if (raw.excd !== profile.exchange) throw new KisMasterError('source_mismatch');
    if (raw.stis !== '3' && ['001', '002', '003', '004', '005', '006'].includes(raw.etyp)) throw new KisMasterError('classification_conflict');
    distinct(raw.symb, symbols); distinct(raw.rsym, realtime);
    if (!(raw.enam.trim() || raw.knam.trim())) throw new KisMasterError('schema_drift');
    return { source_line: start + index + 1, raw };
  });
  const entries = records.map(record => usEntry(record, profile.filename));
  return KisUsMasterParseResultSchema.parse({ metadata: metadata(p, records.length), records,
    directory: directory(p, entries, `Supplied ${profile.filename} only; official 24-column layout checked. US/exchange source guards passed; authenticity, current listing status and complete exchange coverage are not verified.`) });
}

export function parseKisDomesticIndexMaster(contents: string | Uint8Array, context: unknown) {
  const p = prepare(contents, context);
  if (p.context.profile !== 'kr_index_derivatives' || p.context.header_mode !== 'none') throw new KisMasterError('invalid_input');
  const symbols = new Set<string>(); const standards = new Set<string>();
  const records = p.lines.map((line, index) => {
    const row = KisDomesticIndexMasterRawSchema.safeParse(fields(INDEX_KEYS, splitRecord(line, '|')));
    if (!row.success) throw new KisMasterError('schema_drift');
    distinct(row.data.shrn_iscd, symbols); distinct(row.data.stnd_iscd, standards);
    if (!row.data.kor_name.trim()) throw new KisMasterError('schema_drift');
    return { source_line: index + 1, raw: row.data };
  });
  const entries = records.map(indexEntry);
  return KisDomesticIndexMasterParseResultSchema.parse({ metadata: metadata(p, records.length), records,
    directory: directory(p, entries, 'Supplied fo_idx_code_mts.mst only; official nine-column index-derivative layout checked. Options, spreads and unknown types stay unknown; current listing, source authenticity, currency and exchange remain unverified.') });
}

